-- Trigger execution does not require the caller to have function EXECUTE -- privileges. Keep the profile trigger helper unavailable for direct calls. revoke all on function private.handle_new_user() from public, anon, authenticated, service_role;  -- Cover the remaining foreign-key lookups surfaced by the Supabase advisor. create index if not exists audit_logs_admin_created_idx on public.audit_logs (admin_user_id, created_at desc); create index if not exists order_items_product_idx on public.order_items (product_id); create index if not exists order_items_offer_idx on public.order_items (offer_id) where offer_id is not null;